### Código Atualizado:
```cpp
#include <iostream>
#include <fstream>
#include <filesystem>
#include <vector>
#include <string>
#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    CryptoPP::FileSource(filePath.c_str(), true,
        new CryptoPP::HashFilter(hash,
            new CryptoPP::HexEncoder(
                new CryptoPP::StringSink(digest), true)));

    return digest;
}

int main() {
    // Abre o arquivo de saída como "rTalesHash.txt"
    std::ofstream outputFile("rTalesHash.txt");
    if (!outputFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo de saída 'rTalesHash.txt'!" << std::endl;
        return 1;
    }

    std::vector<std::string> extensions = { ".exe", ".dll", ".asi" };

    // Lista de arquivos no diretório atual
    for (const auto& entry : fs::directory_iterator(fs::current_path())) {
        if (entry.is_regular_file()) {
            std::string extension = entry.path().extension().string();
            if (std::find(extensions.begin(), extensions.end(), extension) != extensions.end()) {
                std::string filePath = entry.path().string();
                std::string hash = calculateKeccak512(filePath);

                // Escreve o resultado no arquivo de hashes
                outputFile << "\"" << entry.path().filename().string() << "\" : " << hash << std::endl;
            }
        }
    }

    outputFile.close();
    std::cout << "Hashes calculados e salvos em rTalesHash.txt" << std::endl;

    // Mostra a lista dos arquivos encontrados
    std::cout << "\nLista de arquivos encontrados:\n";
    for (const auto& entry : fs::directory_iterator(fs::current_path())) {
        if (entry.is_regular_file()) {
            std::cout << "- " << entry.path().filename().string() << '\n';
        }
    }

    // Pede ao usuário qual arquivo ele quer processar para criar outro arquivo rTales.ini
    std::cout << "\nDigite o nome do arquivo (ex: 'example.exe') para gerar seu hash e salvar em rTales.ini: ";
    std::string choice;
    std::getline(std::cin, choice); // Lê a escolha do usuário

    // Verifica se o arquivo existe
    if (fs::exists(choice)) {
        std::ofstream newOutputFile("rTales.ini");
        if (newOutputFile.is_open()) {
            newOutputFile << "\"" << choice << "\" : " << calculateKeccak512(choice) << std::endl;
            newOutputFile.close();
            std::cout << "Arquivo criado em rTales.ini com o hash de " << choice << std::endl;
        } else {
            std::cerr << "Falha ao escrever em rTales.ini." << std::endl;
        }
    } else {
        std::cout << "Arquivo não encontrado: " << choice << std::endl;
    }

    return 0;
}
```

### Explicação das Mudanças:
1. **Nome do Arquivo de Hash**:
   - Alterado de `"rTales.ini"` para `"rTalesHash.txt"` na linha `std::ofstream outputFile("rTalesHash.txt");`.

2. **Lista de Arquivos e Seleção do Usuário**:
